import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';

function Login() {
  const navigate = useNavigate();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');

  const handleSubmit = (e) => {
    e.preventDefault();
    navigate('/choose-role');
  };

  return (
    <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: '100vh', background: '#F8F9FA', padding: '20px' }}>
      <div style={{ width: '100%', maxWidth: '402px', background: 'white', padding: '32px 24px', borderRadius: '16px', boxShadow: '0 4px 12px rgba(0,0,0,0.08)' }}>
        <div style={{ textAlign: 'center', marginBottom: '24px' }}>
          <h1 style={{ fontSize: '28px', fontWeight: 800, color: '#0D9488' }}>WORKIE</h1>
          <p style={{ fontSize: '14px', color: '#475569' }}>Easy Work From Home</p>
        </div>
        <h2 style={{ fontSize: '24px', fontWeight: 700 }}>Selamat Datang!</h2>
        <p style={{ color: '#475569', marginBottom: '24px' }}>Masuk untuk mulai merekrut atau mencari kerja instan.</p>
        <form onSubmit={handleSubmit}>
          <div style={{ marginBottom: '16px' }}>
            <label style={{ display: 'block', fontSize: '14px', fontWeight: 600, marginBottom: '6px' }}>Nomor HP atau Email</label>
            <input type="text" placeholder="Contoh: +62812345678" value={email} onChange={(e) => setEmail(e.target.value)} style={{ width: '100%', padding: '12px 16px', border: '1px solid #E2E8F0', borderRadius: '12px', fontSize: '15px' }} />
          </div>
          <div style={{ marginBottom: '16px' }}>
            <label style={{ display: 'block', fontSize: '14px', fontWeight: 600, marginBottom: '6px' }}>Kata Sandi</label>
            <input type="password" placeholder="Masukkan kata sandi Anda" value={password} onChange={(e) => setPassword(e.target.value)} style={{ width: '100%', padding: '12px 16px', border: '1px solid #E2E8F0', borderRadius: '12px', fontSize: '15px' }} />
          </div>
          <div style={{ textAlign: 'right', marginBottom: '20px' }}><Link to="/" style={{ color: '#0D9488', fontSize: '14px' }}>Lupa Kata Sandi?</Link></div>
          <button type="submit" style={{ width: '100%', padding: '14px', background: '#0D9488', color: 'white', border: 'none', borderRadius: '12px', fontSize: '16px', fontWeight: 700 }}>Masuk</button>
        </form>
        <div style={{ textAlign: 'center', margin: '16px 0' }}><Link to="/register" style={{ color: '#0D9488', fontWeight: 600 }}>Daftar Akun Baru</Link></div>
        <div style={{ textAlign: 'center' }}>
          <p style={{ color: '#475569', fontSize: '14px', marginBottom: '12px' }}>Atau masuk dengan</p>
          <div style={{ display: 'flex', gap: '12px' }}>
            <button style={{ flex: 1, padding: '12px', border: '1px solid #E2E8F0', borderRadius: '12px', background: 'white', fontSize: '14px', fontWeight: 600 }}>G Google</button>
            <button style={{ flex: 1, padding: '12px', border: '1px solid #E2E8F0', borderRadius: '12px', background: 'white', fontSize: '14px', fontWeight: 600 }}>© Apple</button>
          </div>
        </div>
        <div style={{ textAlign: 'center', marginTop: '16px' }}><Link to="/choose-role" style={{ color: '#475569', fontSize: '14px' }}>Guest</Link></div>
      </div>
    </div>
  );
}

export default Login;
